node --input-type=module << 'EOF'
import {createRequire} from 'module';
const require = createRequire(import.meta.url);
const ts = require('./node_modules/typescript/lib/typescript.js');

const code = `
import Ajv from 'ajv';
import type {ValidateFunction} from 'ajv';

interface AjvError { instancePath?: string; keyword?: string; message?: string; }
const ajv = new Ajv({strict: false, validateFormats: false});
export class ToolRegistry {
  private readonly schemaCache = new WeakMap<object, ValidateFunction>();
}
`;

const result = ts.transpileModule(code, {
  compilerOptions: {
    target: ts.ScriptTarget.ES2022,
    module: ts.ModuleKind.NodeNext,
    moduleResolution: ts.ModuleResolutionKind.NodeNext,
    strict: true,
    isolatedModules: true,
    esModuleInterop: true,
  },
  reportDiagnostics: true,
});

console.log('diagnostics:', result.diagnostics?.length, result.diagnostics?.map(d => d.code));
// Check if 'strict: false' is preserved in the output
const hasStrict = result.outputText.includes('strict: false') || result.outputText.includes('"strict"');
console.log('output contains strict:', hasStrict);
console.log('relevant output:', result.outputText.match(/new Ajv\([^)]+\)/)?.[0]);
EOF
